def _ordered_pairs(config, events, items):
    """link-wire 记录按实际处理顺序排列：同刻按端口配置序、advance 居末，
    同键保持输入相对序（与 link_wire 内稳定排序同键）；(event, item)
    成对按同一置换重排。其余模式保持输入顺序。
    """
    mode = _log_mode(config, events)
    if mode != "link_wire":
        return list(zip(events, items))
    order = {
        port["name"]: i for i, port in enumerate(config["ports"])
        if isinstance(port, dict)
    }
    port_count = len(order)
    pairs = list(zip(events, items))
    pairs.sort(
        key=lambda pair: (
            pair[0]["t"],
            port_count
            if frozenset(pair[0]) == LINK_WIRE_ADVANCE_EVENT_KEYS
            else order[pair[0]["port"]],
        )
    )
    return pairs

